getLabel.example:
// client
const { Hud, Key } = kcds.ui;

Hud.showNotification(`Press ${Key.getLabel('e')} to open`);

bind.example:
// client
const { Key } = kcds.ui;

Key.bind('f', () => {
  kcds.core.Events.toServer('openDoor');
});
Key.bind('shift', 'both', (key, edge) => {
  console.log(`${key} ${edge}`);
});

bind.exampleCs:
// client

Key.Bind("f", new Action(() =>
{
    Events.ToServer("openDoor");
}));
Key.Bind("shift", "both", (JsValue key, JsValue edge) =>
{
    Log.Info($"{key} {edge}");
});
